    const fTxt = go.kind === 'now' ? (go.f === 'yes' ? 'АИ-95' : go.f === 'part' ? 'АИ-92' : 'дизель') : go.kind === 'stale' ? 'не точно — проверь' : 'окно по прогнозу';
    const goSub = el('pulseGoSub');
