      { id: 'fuelheat-hot-old', cls: 'hot-old', ramp: ['rgba(239,83,80,0)', 'rgba(239,83,80,0.18)', 'rgba(239,83,80,0.28)', 'rgba(239,83,80,0.35)', 'rgba(239,83,80,0.45)'] }
