// ============================================================
// KB INSTANT ADVISOR v1 — «Куда ехать» видно сразу, а не после
// всех запросов. 1) Снимок топ-3 советника в localStorage.
// 2) Линза и счётчики мини-меню рисуются сразу после первого
//    кадра (станции+отметки), не дожидаясь прогнозов/цен/голосов.
// 3) На первом заходе — прошлый снимок с честной пометкой времени.
// 4) Как только данные доехали — тихая замена на свежие.
// Вставить в САМЫЙ КОНЕЦ app.js. index.html не менять.
// ============================================================
(function () {
'use strict';
if (window.__kbInstantAdv) return;
window.__kbInstantAdv = 1;
var KEY = 'kbAdvSnap';
function hhmm(t) { var d = new Date(t); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); }
function readSnap() {
try {
var s = JSON.parse(localStorage.getItem(KEY) || 'null');
if (s && s.items && s.items.length && s.city === userCityKey && Date.now() - s.t < 12 * 3600000) return s;
} catch (e) {}
return null;
}
function writeSnap(list) {
try {
localStorage.setItem(KEY, JSON.stringify({
t: Date.now(), city: userCityKey,
items: list.slice(0, 3).map(function (it) {
return { id: it.st.id, name: it.st.name || 'АЗС', addr: it.st.address || '', kind: it.kind, km: it.km, f: it.f };
})
}));
} catch (e) {}
}
function paintLens(name, sub) {
var v = document.getElementById('lentiAdvV'), s = document.getElementById('lentiAdvS');
if (v && name) v.textContent = name;
if (s && sub) s.textContent = sub;
}
function paintBadge(n) {
try {
var b = document.querySelector('#kbQmMenu3 [data-kbq3="1"] .kbq3-badge');
if (b && (b.textContent || '').trim() === '0' && n > 0) b.textContent = String(n);
} catch (e) {}
}
function instant() {
try {
var have = typeof allStations !== 'undefined' && allStations.length &&
typeof allLastObs !== 'undefined' && Object.keys(allLastObs).length;
if (have) {
var list = [];
try { list = buildAdviceList() || []; } catch (e) {}
if (list.length) {
writeSnap(list);
var it = list[0];
paintLens(it.st.name || 'АЗС',
it.kind === 'now' ? 'топливо есть сейчас · тап — подборка'
: it.kind === 'stale' ? 'источник утверждает топливо · тап — подборка'
: 'ближайшее окно привоза · тап — подборка');
paintBadge(list.filter(function (x) { return x.kind === 'now'; }).length);
return;
}
}
var s = readSnap();
if (s) {
var x = s.items[0];
paintLens(x.name, 'по данным на ' + hhmm(s.t) + ' · тап — подборка');
paintBadge(s.items.filter(function (i) { return i.kind === 'now'; }).length);
}
} catch (e) {}
}
var _rs = renderStations;
renderStations = function (list) { var r = _rs(list); instant(); return r; };
if (window.__kbPipe) {
window.__kbPipe.now.push(function () { setTimeout(instant, 0); });
window.__kbPipe.soft.push(function () { setTimeout(instant, 0); });
}
setTimeout(instant, 250);
setTimeout(instant, 1200);
})();
// ============================================================
// KB NO SERVICE BORDER v1 — убираем синюю границу области обслуживания.
// Она рисовалась на 2D-канвасе КАЖДЫЙ кадр движения карты (проекция кольца,
// queryRenderedFeatures воды, зебра, evenodd-клипы) и убивала плавность.
// Теперь канвас рисует ТОЛЬКО маршрут пользователя; без маршрута он пустой
// и не выполняет никакой работы на панораме/зуме. Маршрут и его вуаль сохранены.
// Вставить в САМЫЙ КОНЕЦ app.js. index.html не менять.
// ============================================================
(function () {
'use strict';
if (window.__kbNoServiceBorder) return;
window.__kbNoServiceBorder = 1;
try { serviceRing = null; } catch (e) {}
try { applyServiceZoom = function () {}; } catch (e) {}
drawRouteCanvasNow = function () {
var cv = document.getElementById('routeCanvas');
if (!cv || typeof mapObj === 'undefined' || !mapObj) return;
if (!routeFeature || !routeFeature.geometry) {
if (cv.width !== 0 || cv.height !== 0) { cv.width = 0; cv.height = 0; }
return;
}
var box = mapObj.getContainer().getBoundingClientRect();
var dpr = window.devicePixelRatio || 1;
var W = Math.max(1, Math.round(box.width * dpr)), H = Math.max(1, Math.round(box.height * dpr));
if (cv.width !== W || cv.height !== H) { cv.width = W; cv.height = H; }
var g = cv.getContext('2d');
g.setTransform(dpr, 0, 0, dpr, 0, 0);
g.clearRect(0, 0, box.width, box.height);
var coords = routeFeature.geometry.coordinates;
var step = Math.max(1, Math.floor(coords.length / 400));
var pts = [];
for (var i = 0; i < coords.length; i += step) pts.push(mapObj.project([coords[i][0], coords[i][1]]));
var lc = coords[coords.length - 1];
pts.push(mapObj.project([lc[0], lc[1]]));
var trace = function () {
g.beginPath();
g.moveTo(pts[0].x, pts[0].y);
for (var k = 1; k < pts.length - 1; k++) {
var mx = (pts[k].x + pts[k + 1].x) / 2, my = (pts[k].y + pts[k + 1].y) / 2;
g.quadraticCurveTo(pts[k].x, pts[k].y, mx, my);
}
var lp = pts[pts.length - 1];
g.lineTo(lp.x, lp.y);
};
g.lineJoin = 'round'; g.lineCap = 'round';
var veil = Math.max(0, Math.min(1, (15.2 - mapObj.getZoom()) / 1.2));
if (veil > 0.02) {
g.fillStyle = 'rgba(20,33,61,' + (0.22 * veil).toFixed(3) + ')';
g.fillRect(0, 0, box.width, box.height);
g.globalCompositeOperation = 'destination-out';
trace(); g.strokeStyle = 'rgba(0,0,0,' + veil.toFixed(3) + ')'; g.lineWidth = 26; g.stroke();
trace(); g.strokeStyle = 'rgba(0,0,0,' + (0.6 * veil).toFixed(3) + ')'; g.lineWidth = 46; g.stroke();
trace(); g.strokeStyle = 'rgba(0,0,0,' + (0.3 * veil).toFixed(3) + ')'; g.lineWidth = 68; g.stroke();
trace(); g.strokeStyle = 'rgba(0,0,0,' + (0.12 * veil).toFixed(3) + ')'; g.lineWidth = 120; g.stroke();
g.globalCompositeOperation = 'source-over';
}
trace(); g.strokeStyle = 'rgba(23,70,200,.16)'; g.lineWidth = 12; g.stroke();
trace(); g.strokeStyle = 'rgba(255,255,255,.95)'; g.lineWidth = 8.5; g.stroke();
trace(); g.strokeStyle = '#2465ee'; g.lineWidth = 5; g.stroke();
};
})();
